CREATE TABLE "Player" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "name" TEXT NOT NULL, "position" TEXT NOT NULL, "sourceType" TEXT NOT NULL, "sourceNamespace" TEXT, "externalId" TEXT, "custom" INTEGER NOT NULL DEFAULT 0, "explicitMinimumBid" INTEGER, "available" INTEGER NOT NULL DEFAULT 1, "keeperEligible" INTEGER NOT NULL DEFAULT 0, "activeImportBatchId" TEXT, "createdAt" TEXT NOT NULL, "updatedAt" TEXT NOT NULL, FOREIGN KEY ("seasonId") REFERENCES "Season"("id"), UNIQUE("seasonId", "sourceType", "sourceNamespace", "externalId"));
CREATE TABLE "PlayerImportBatch" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "sourceNamespace" TEXT NOT NULL, "format" TEXT NOT NULL, "sha256" TEXT NOT NULL, "rowCount" INTEGER NOT NULL, "supersedesId" TEXT, "supersededAt" TEXT, "createdAt" TEXT NOT NULL, FOREIGN KEY ("seasonId") REFERENCES "Season"("id"), UNIQUE("seasonId", "sourceNamespace", "sha256"));
CREATE TABLE "PositionPriceFloor" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "position" TEXT NOT NULL, "minimumBid" INTEGER NOT NULL CHECK("minimumBid" > 0), FOREIGN KEY ("seasonId") REFERENCES "Season"("id"), UNIQUE("seasonId", "position"));
CREATE TABLE "KeeperSelection" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "seasonTeamId" TEXT NOT NULL UNIQUE, "playerId" TEXT NOT NULL UNIQUE, "cost" INTEGER NOT NULL DEFAULT 50, "startingBudget" INTEGER NOT NULL, "createdAt" TEXT NOT NULL, FOREIGN KEY ("seasonId") REFERENCES "Season"("id"), FOREIGN KEY ("seasonTeamId") REFERENCES "SeasonTeam"("id"), FOREIGN KEY ("playerId") REFERENCES "Player"("id"));
UPDATE "SchemaMetadata" SET "version"=2, "applicationVersion"='0.2.0' WHERE "singleton"=1;
